// Wars and Fronts Pt.2. "All the stats should be able to be manually done by
// the scenario designer or generated by the ai." And rated together: "remove
// region count power entirely, have it be generated by the ai for every
// country by the scenario designer and that then ships with the scenario (like
// how politics generation works except everything is relative to every other
// country it generates and it doesnt waste an entire tool call per country or
// whatever, it does 20 countries per api call)"; "if it is not pregenerated, it
// should just generate it whenever it is needed for the game for a country"
// (the owner, 2026-10-16).
//
// One request rates up to MILITARY_BATCH_MOST polities at once, each against
// the others: those it rates and those already rated, which it is shown as the
// scale its figures keep to. Where nobody is rated yet, it is shown the world's
// polities and rates the strongest of them first, so that the scale is set by
// them. It gives each polity's people too, for those whose people nobody
// knows: a country's people are what its weight in a war is counted from
// (runtime/countryWeight.js), and never the land it holds. It is asked
//
//   by a scenario's designer, for every country and group at once
//   (GameUI/ScenarioMilitaryPanel.jsx): what it says ships with the scenario;
//   in a game, for the countries the game needs and has no figures for
//   (gameplay.js ensureMilitaryFigures): a war's, the ranking's, a country's
//   own Stats pane's;
//   in the Workshop, for one country ("Fill in with AI" on its Military block),
//   against the scenario's others.
//
// Its figures are the game's own (runtime/militaryStats.js): quality,
// technology, land, sea, air and spending from 0 to 100 (50 an ordinary army of
// its era; an arm at 0 is none at all), the share of its people it could call
// up in a war, and the shares of its army that are horse and siege.

import { militaryLookup, normalizeMilitaryStats } from "../../runtime/militaryStats.js";
import { peopleFor } from "../../runtime/militaryPower.js";
import { ERA_LABELS } from "../../runtime/warSettings.js";

const clean = (value) => String(value ?? "").replace(/\s+/g, " ").trim();
const fold = (value) => clean(value).toLowerCase();
const list = (value) => (Array.isArray(value) ? value : []);

// How many polities one request rates.
export const MILITARY_BATCH_MOST = 20;
// The most polities already rated a request is shown as its scale, and the most of a world's it picks from.
export const MILITARY_SCALE_MOST = 260;
// The figures the AI rates (the rest, weariness, the men a counter stands for and the mustering curve, are the
// designer's own).
export const MILITARY_RATED_FIELDS = Object.freeze(["quality", "technology", "land", "sea", "air", "spending", "manpowerShare", "cavalryShare", "siegeShare"]);

// What each figure means, as every request that rates them says it (conflictBackends.js too).
export const MILITARY_RELATIVE_LINE = "Rate every polity AGAINST THE OTHERS, on one scale for the whole world: those you rate now and those already rated. Of two polities, the one whose soldiers fight better has the higher quality; the better armed, the higher technology; the stronger on land, at sea or in the air, the higher figure there; the better funded, the higher spending. The strongest of the world in a respect is 85 to 95 in it.";
export const MILITARY_FIGURE_LINES = Object.freeze([
  "quality: how well its soldiers fight (a peasant levy or raw conscripts about 20, professional regulars 60 to 70, a renowned elite such as knights, legions or guards 80 and up).",
  "technology: what they fight with, against the best of its era (backward 20, ordinary 50, the most advanced 80 and up).",
  "land, sea, air: what it can do on land, at sea and in the air. 0 means it cannot fight there at all: a people that never goes to sea has sea 0; before aircraft every polity has air 0.",
  "spending: what its forces have to spend for each soldier, against the other polities' (the best funded of the world 85 and up, an ordinary army 50, a poor one 20).",
  "And: manpowerShare, the percent of its people it could call up in a war: every man fit to serve, not the army it keeps now (12 is ordinary, and few are below 8; a warrior people or an order of fighting men far more); cavalryShare and siegeShare, the shares of its army that are horse (armour in modern times) and siege engines (artillery), each from 0 to 1.",
]);
export const MILITARY_EXAMPLE = '{"quality":50,"technology":50,"land":50,"sea":50,"air":50,"spending":50,"manpowerShare":12,"cavalryShare":0.15,"siegeShare":0.1}';

// Only the figures the AI rates, held to what the game keeps; null for none.
export const ratedFigures = (value) => {
  const figures = normalizeMilitaryStats(value);
  if (!figures) return null;
  const out = {};
  for (const field of MILITARY_RATED_FIELDS) if (figures[field] !== undefined) out[field] = figures[field];
  return Object.keys(out).length > 0 ? out : null;
};

// Whether a polity's figures want rating: one of those the AI rates is missing.
export const wantsRating = (military) => MILITARY_RATED_FIELDS.some((field) => military?.[field] === undefined || military?.[field] === null || military?.[field] === "");

const people = (value) => {
  const count = Number(value);
  return Number.isFinite(count) && count >= 1 ? Math.round(count) : 0;
};

// A polity's figures as a request shows them: "quality 60, technology 75, land 80, sea 50, air 75, spending 60,
// 10% of its people fit to call up, its people 146000000".
export const describeMilitary = (military, population = 0) => {
  const parts = [];
  for (const field of ["quality", "technology", "land", "sea", "air", "spending"]) {
    const value = Number(military?.[field]);
    if (military?.[field] !== undefined && military?.[field] !== null && Number.isFinite(value)) parts.push(`${field} ${Math.round(value)}`);
  }
  const share = Number(military?.manpowerShare);
  if (military?.manpowerShare !== undefined && military?.manpowerShare !== null && Number.isFinite(share)) parts.push(`${Math.round(share * 10) / 10}% of its people fit to call up`);
  if (people(population) > 0) parts.push(`its people ${people(population)}`);
  return parts.join(", ");
};

// The request.
//   polities   [{ name, note?, population? }]: the polities to rate, at most MILITARY_BATCH_MOST, each under its
//              exact name; `population` where its people are known (else it is asked for them)
//   pickFrom   or, where nobody is rated yet: [{ name, population? }], the world's polities, of which it rates the
//              `pick` with the strongest militaries
//   rated      [{ name, military, population? }]: the polities already rated, the scale it keeps to
//   date, era, rules   the scenario's date, the era its wars are fought in (0 to 3, or null), its own rules
// Returns { systemPrompt, userMessage, asked }: `asked`, the exact names an answer may give figures for.
export const militaryRatingRequest = ({ polities = [], pickFrom = [], pick = MILITARY_BATCH_MOST, rated = [], date = "", era = null, rules = "" } = {}) => {
  const picking = list(polities).length === 0 && list(pickFrom).length > 0;
  const asked = (picking ? list(pickFrom) : list(polities).slice(0, MILITARY_BATCH_MOST))
    .map((entry) => ({ name: clean(entry?.name), note: clean(entry?.note), population: people(entry?.population) }))
    .filter((entry) => entry.name)
    .slice(0, picking ? MILITARY_SCALE_MOST : MILITARY_BATCH_MOST);
  const most = Math.max(1, Math.min(MILITARY_BATCH_MOST, Math.floor(Number(pick) || MILITARY_BATCH_MOST)));
  const scale = list(rated)
    .map((entry) => ({ name: clean(entry?.name), line: describeMilitary(entry?.military, entry?.population) }))
    .filter((entry) => entry.name && entry.line)
    .slice(0, MILITARY_SCALE_MOST);
  const systemPrompt = [
    "You are Open Historia's military assessor. You rate how polities make war, for the game's battle engine.",
    MILITARY_RELATIVE_LINE,
    "Each of these is a whole number from 0 to 100, where 50 is an ordinary army of its era:",
    ...MILITARY_FIGURE_LINES,
    "population: its people, as a plain count, for every polity you rate (a polity whose people you are given: that figure).",
    "Go by the era, the world as described and what is said of each polity. Leave out a figure you cannot judge.",
    "",
    "Return exactly one JSON object and no markdown:",
    `{"polities":[{"polity":"the exact name you were given","population":0,"military":${MILITARY_EXAMPLE}}]}`,
    picking
      ? `Rate the ${most} polities of the list whose militaries are the strongest, one entry each, under the exact names given.`
      : "One entry for every polity you are asked to rate, in the order given, each under the exact name given.",
  ].join("\n");
  // (What the scenario says of a polity it is asked to rate; not of every polity of a world it picks from.)
  const line = (entry) => `- ${entry.name}${entry.population > 0 ? `; its people ${entry.population}` : ""}${!picking && entry.note ? `; what the scenario says of it: ${entry.note.slice(0, 400)}` : ""}`;
  const userMessage = [
    clean(date) ? `The scenario's date: ${clean(date)}` : "",
    Number.isInteger(era) && ERA_LABELS[era] ? `The era its wars are fought in: ${ERA_LABELS[era]}` : "",
    clean(rules) ? `ERA & WORLD RULES:\n${String(rules).trim().slice(0, 1800)}` : "",
    scale.length > 0
      ? `ALREADY RATED (the scale your figures keep to; do not return these):\n${scale.map((entry) => `- ${entry.name}: ${entry.line}`).join("\n")}`
      : "",
    picking
      ? `THE WORLD'S POLITIES (${asked.length}), nobody rated yet:\n${asked.map(line).join("\n")}\n\nRATE the ${most} of these whose militaries are the strongest, so that every other polity can be rated against them.`
      : `RATE ${asked.length === 1 ? "THIS ONE" : `THESE (${asked.length})`}:\n${asked.map(line).join("\n")}`,
  ].filter(Boolean).join("\n\n");
  return { systemPrompt, userMessage, asked: asked.map((entry) => entry.name), picking, most };
};

// The answer's figures for one polity, held to what the game keeps; null for none usable.
export const readMilitaryRating = (payload) => ratedFigures(payload?.military ?? payload);

// The answer, for each polity asked of that it rated usably: [{ name, population?, military? }] under the names asked,
// each once.
export const readMilitaryRatings = (payload, names) => {
  const wanted = new Map(list(names).map((name) => [fold(name), clean(name)]).filter(([key]) => key));
  const entries = Array.isArray(payload?.polities) ? payload.polities : Array.isArray(payload) ? payload : [];
  // (One polity asked of, answered without the list: its figures alone.)
  if (entries.length === 0 && wanted.size === 1) {
    const military = readMilitaryRating(payload);
    const count = people(payload?.population);
    return military || count > 0 ? [{ name: [...wanted.values()][0], ...(count > 0 ? { population: count } : {}), ...(military ? { military } : {}) }] : [];
  }
  const read = [];
  const seen = new Set();
  for (const entry of entries) {
    const key = fold(entry?.polity ?? entry?.country ?? entry?.name);
    if (!wanted.has(key) || seen.has(key)) continue;
    const military = ratedFigures(entry?.military);
    const count = people(entry?.population);
    if (!military && count === 0) continue;
    seen.add(key);
    read.push({ name: wanted.get(key), ...(count > 0 ? { population: count } : {}), ...(military ? { military } : {}) });
  }
  return read;
};

// One request, made by whoever asks it outright (the Scenario Editor, the Workshop): `call(systemPrompt, messages,
// options)` is the AI (main.jsx callAI where none is given). Resolves to readMilitaryRatings; throws when the AI could
// not be asked or said nothing usable.
export const rateMilitaryBatch = async (options = {}, { call = null } = {}) => {
  const { systemPrompt, userMessage, asked } = militaryRatingRequest(options);
  if (asked.length === 0) return [];
  const [ask, { extractJsonPayload }] = await Promise.all([
    typeof call === "function" ? call : import("./main.jsx").then((module) => module.callAI),
    import("./jsonSalvage.js"),
  ]);
  const response = await ask(systemPrompt, [{ role: "user", parts: [{ text: userMessage }] }], { reasoningEnabled: false, logLabel: "military figures" });
  const rawText = typeof response === "string" ? response : clean(response?.rawText);
  const read = readMilitaryRatings(response?.toolInput ?? extractJsonPayload(rawText), asked);
  if (read.length === 0) throw new Error("The AI's answer had no figures the game could use.");
  return read;
};

// One country, in the Workshop: its figures against the scenario's others (`rated`).
//   name, note, population   the country; date, era, rules   the scenario's
// Resolves to its figures; throws when the AI could not be asked or said nothing usable.
export const rateMilitaryFigures = async ({ name = "", note = "", population = 0, rated = [], date = "", era = null, rules = "" } = {}, options = {}) => {
  const read = await rateMilitaryBatch({ polities: [{ name, note, population }], rated: list(rated).filter((entry) => fold(entry?.name) !== fold(name)), date, era, rules }, options);
  const figures = read[0]?.military ?? null;
  if (!figures) throw new Error("The AI's answer had no figures the game could use.");
  return figures;
};

// The polities of a world rated already, as a request is shown them for its scale: [{ name, military, population }],
// every one with figures of its own but those in `asking` (the names the request rates), those rated in full first.
//   entries   [{ name, military, population }]
export const ratedScaleOf = (entries, asking = []) => {
  const skip = new Set(list(asking).map(fold));
  const shown = list(entries)
    .filter((entry) => clean(entry?.name) && !skip.has(fold(entry.name)) && describeMilitary(entry?.military))
    .map((entry) => ({ name: clean(entry.name), military: entry.military, population: people(entry.population) }));
  return [...shown.filter((entry) => !wantsRating(entry.military)), ...shown.filter((entry) => wantsRating(entry.military))];
};

// The countries at war whose people or figures nobody knows yet (the members of a war not ended, and the sides of a
// battlefield still open), but those in `skip` (asked of already) and groups (theirs are their scenario designer's:
// a group is no country with a sheet): what the game needs rated before their war is fought much further. Exact
// names, each once.
export const militaryTargets = (world, { skip = [] } = {}) => {
  const lookup = militaryLookup(world);
  const skipped = new Set([...list(skip), ...Object.keys(world?.groups && typeof world.groups === "object" ? world.groups : {})].map(fold));
  const wanted = new Map();
  const add = (name) => {
    const key = fold(name);
    if (!key || skipped.has(key) || wanted.has(key)) return;
    if (wantsRating(lookup(name)) || !(peopleFor(world, name) > 0)) wanted.set(key, clean(name));
  };
  for (const war of list(world?.wars)) {
    if (!war || war.status === "ended") continue;
    for (const side of [war.sideA, war.sideB]) list(side).forEach(add);
  }
  for (const record of list(world?.battlefields)) {
    if (!record || record.status === "closed") continue;
    for (const side of list(record.sides)) list(side).forEach(add);
  }
  return [...wanted.values()];
};
